// -1 when unmapped (v2-new param, or a stale v1 number).
inline int32_t paramIdFromV1Cc(uint16_t v1cc) {
    size_t lo = 0, hi = kCount;
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2;
        if (kByV1Cc[mid].v1cc == v1cc) return kByV1Cc[mid].paramId;
        if (kByV1Cc[mid].v1cc < v1cc)  lo = mid + 1; else hi = mid;
    }
    return -1;
}

inline int32_t v1CcFromParamId(uint16_t paramId) {
    size_t lo = 0, hi = kCount;
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2;
        if (kByParamId[mid].paramId == paramId) return kByParamId[mid].v1cc;
        if (kByParamId[mid].paramId < paramId)  lo = mid + 1; else hi = mid;
    }
    return -1;
}

